from __future__ import annotations
import math


def wall_violated(n: float, alpha: float, beta_s: float, beta_t: float) -> bool:
    """True iff (n-1) ln 2 > ln n + n^(alpha+beta_s+beta_t): then NO covering of [n]
    with |S| <= n^beta_s, |T| <= n^beta_t, max S <= exp(n^alpha) exists."""
    return (n - 1) * math.log(2) > math.log(n) + n ** (alpha + beta_s + beta_t)


def classify_symmetric(alpha: float, beta: float) -> str:
    """Status of (alpha, beta, beta) under the sandwich theorem (0 < beta <= 1)."""
    if alpha + 2 * beta < 1:
        return "impossible (exponent constraint)"
    if alpha > 1 - beta:
        return "feasible (block products with |T| = 1, then monotonicity)"
    return "open (between 1 - 2 beta and 1 - beta)"


def measured_alpha(n: int, ln_M: float) -> float:
    """Unit-correct exponent ln ln M / ln n (pass ln M to avoid overflow)."""
    return math.log(ln_M) / math.log(n)


def first_violation(gamma: float, start_exp: int = 1, stop_exp: int = 300) -> float | None:
    """Smallest power of ten n at which the wall rules out gamma = alpha+beta_S+beta_T."""
    for e in range(start_exp, stop_exp):
        n = 10.0 ** e
        if (n - 1) * math.log(2) > math.log(n) + n ** gamma:
            return n
    return None


if __name__ == "__main__":
    for a, b in [(0.30, 1/3), (1/3, 1/3), (0.5, 1/3), (0.7, 1/3), (0.5, 2/3)]:
        print(f"(alpha,beta)=({a:.3f},{b:.3f}): {classify_symmetric(a, b)}")
    for g in (0.5, 0.9, 0.99):
        print(f"gamma={g}: wall bites from n ~ {first_violation(g):.0e}")
    print("measured alpha for n = 10^6, M = exp(n^(1/3)) (ln M = 100):", measured_alpha(10**6, 100.0))
